 public static void CaptureOriginalWeights(){if(File.Exists(Folder+"/Original_LOD0.bytes"))return;var bundle=AssetBundle.LoadFromFile("C:/Program Files (x86)/Steam/steamapps/common/7 Days To Die/Mods/zzz_REBIRTH__3_0/Resources/rebirth_rebirthnurse.unity3d");try{var model=bundle.LoadAsset<GameObject>("RebirthNurse");foreach(var r in model.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(x=>x.name.StartsWith("LOD")))using(var w=new BinaryWriter(File.Open(Folder+"/Original_"+r.name+".bytes",FileMode.Create))){w.Write(RebirthNurseSourcePreservation.Hash(r.sharedMesh));w.Write(r.bones.Length);foreach(var b in r.bones)w.Write(b.name);var weights=r.sharedMesh.boneWeights;w.Write(weights.Length);foreach(var a in weights){w.Write(a.boneIndex0);w.Write(a.boneIndex1);w.Write(a.boneIndex2);w.Write(a.boneIndex3);w.Write(a.weight0);w.Write(a.weight1);w.Write(a.weight2);w.Write(a.weight3);}}}finally{bundle.Unload(true);}AssetDatabase.Refresh();}
 static BoneWeight[] ReadOriginalWeights(SkinnedMeshRenderer renderer,Dictionary<string,int> ids){using(var r=new BinaryReader(File.OpenRead(Folder+"/Original_"+renderer.name+".bytes"))){if(r.ReadString()!=RebirthNurseSourcePreservation.Hash(renderer.sharedMesh))return renderer.sharedMesh.boneWeights;int n=r.ReadInt32();var map=new int[n];for(int i=0;i<n;i++)map[i]=ids[r.ReadString()];n=r.ReadInt32();var weights=new BoneWeight[n];for(int i=0;i<n;i++)weights[i]=new BoneWeight{boneIndex0=map[r.ReadInt32()],boneIndex1=map[r.ReadInt32()],boneIndex2=map[r.ReadInt32()],boneIndex3=map[r.ReadInt32()],weight0=r.ReadSingle(),weight1=r.ReadSingle(),weight2=r.ReadSingle(),weight3=r.ReadSingle()};return weights;}}
 static float[] HairStrength(Mesh mesh,Vector3[] p,Vector2[] uv,Texture2D albedo){var s=new float[p.Length];for(int i=0;i<p.Length;i++){var c=albedo.GetPixelBilinear(uv[i].x,uv[i].y);bool blue=c.b>c.r*1.13f&&c.g>c.r*1.05f;bool loose=p[i].y>1.32f&&p[i].y<1.72f&&Mathf.Abs(p[i].x)<.205f&&(p[i].z<-.105f||(Mathf.Abs(p[i].x)>.105f&&p[i].y>1.37f&&p[i].z<.12f));if(loose&&!blue)s[i]=Mathf.SmoothStep(0,1,Mathf.Clamp01((1.72f-p[i].y)/.085f))*.9f;}
 var groups=Enumerable.Range(0,p.Length).GroupBy(i=>new Vector3Int(Mathf.RoundToInt(p[i].x*100000),Mathf.RoundToInt(p[i].y*100000),Mathf.RoundToInt(p[i].z*100000))).Select(g=>g.ToArray()).ToArray();var tris=mesh.triangles;var pinned=(float[])s.Clone();for(int t=0;t<tris.Length;t+=3){int a=tris[t],b=tris[t+1],c=tris[t+2];if(Mathf.Min(s[a],Mathf.Min(s[b],s[c]))<=.001f){pinned[a]=0;pinned[b]=0;pinned[c]=0;}}s=pinned;
 for(int pass=0;pass<12;pass++){foreach(var g in groups){float minimum=g.Min(i=>s[i]);foreach(int i in g)s[i]=minimum;}var next=(float[])s.Clone();for(int t=0;t<tris.Length;t+=3)for(int edge=0;edge<3;edge++){int a=tris[t+edge],b=tris[t+(edge+1)%3];float limit=.1f;next[a]=Mathf.Min(next[a],s[b]+limit);next[b]=Mathf.Min(next[b],s[a]+limit);}s=next;}
 foreach(var g in groups){float minimum=g.Min(i=>s[i]);foreach(int i in g)s[i]=minimum;}return s;}
 static BoneWeight Sorted(BoneWeight w){int[] ids={w.boneIndex0,w.boneIndex1,w.boneIndex2,w.boneIndex3};float[] ws={w.weight0,w.weight1,w.weight2,w.weight3};Array.Sort(ws,ids);Array.Reverse(ws);Array.Reverse(ids);float sum=ws.Sum();return new BoneWeight{boneIndex0=ids[0],weight0=ws[0]/sum,boneIndex1=ids[1],weight1=ws[1]/sum,boneIndex2=ids[2],weight2=ws[2]/sum,boneIndex3=ids[3],weight3=ws[3]/sum};}
 static void ImproveImports(){var normalPath=AssetDatabase.LoadAssetAtPath<GameObject>(RebirthNurseNativeAssembly.PrefabPath).GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="LOD0").sharedMaterial.GetTexture("_Normal");var normal=(TextureImporter)AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(normalPath));normal.maxTextureSize=2048;normal.textureCompression=TextureImporterCompression.CompressedHQ;normal.compressionQuality=100;var np=normal.GetPlatformTextureSettings("Standalone");np.overridden=true;np.maxTextureSize=2048;np.format=TextureImporterFormat.BC5;np.compressionQuality=100;normal.SetPlatformTextureSettings(np);normal.SaveAndReimport();foreach(string path in AssetDatabase.FindAssets("t:Texture2D",new[]{RebirthNurseSkinMaterials.Folder}).Select(AssetDatabase.GUIDToAssetPath).Where(x=>x.Contains("Albedo"))){var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.maxTextureSize=2048;importer.textureCompression=TextureImporterCompression.CompressedHQ;importer.compressionQuality=100;var platform=importer.GetPlatformTextureSettings("Standalone");platform.overridden=true;platform.maxTextureSize=2048;platform.format=TextureImporterFormat.BC7;platform.compressionQuality=100;importer.SetPlatformTextureSettings(platform);importer.SaveAndReimport();}}
